/**
 * Course Enrolments table (PRO; in both editions, loaded only when PRO is active, its web service exists only
 * with classes/pro/): a row click (or Enter / Space) opens the student details modal.
 * Plain AMD (no build step needed); amd/build/student.min.js is a copy of this file.
 *
 * @module     report_alucoursecompletion/student
 * @copyright  2026 Alumisoft developer@alumisoft.com
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(['core/ajax', 'core/templates', 'core/modal', 'core/notification', 'core/str'],
function(Ajax, Templates, ModalModule, Notification, Str) {
    var Modal = ModalModule.default || ModalModule;
    var Tpl = Templates.default || Templates;
    var BADGES = {
        incomplete: 'bg-secondary text-dark',
        complete: 'bg-success text-white',
        pass: 'bg-success text-white',
        fail: 'bg-warning text-dark'
    };
    var ROW = 'tr.report-alucoursecompletion-row';
    var CELL = '.report-alucoursecompletion-student';

    // Details already requested (prefetched on hover), kept for 60 seconds.
    var CACHE_MS = 60000;
    var cache = {};

    var escape = function(text) {
        var div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    };

    var fetchStudent = function(userid, courseid) {
        var key = userid + '_' + courseid;
        var hit = cache[key];
        if (hit && Date.now() - hit.time < CACHE_MS) {
            return hit.request;
        }
        var request = Ajax.call([{
            methodname: 'report_alucoursecompletion_get_student_details',
            args: {userid: userid, courseid: courseid}
        }])[0];
        cache[key] = {time: Date.now(), request: request};
        request.catch(function() {
            delete cache[key];
        });
        return request;
    };

    var openStudent = function(userid, courseid) {
        var request = fetchStudent(userid, courseid);
        var body = request.then(function(data) {
            return Tpl.render('report_alucoursecompletion/student_details', {
                exports: data.exports,
                hasexports: data.exports.length > 0,
                haspercent: data.percent >= 0,
                percent: data.percent,
                profile: data.profile,
                summary: data.summary,
                hasactivities: data.activities.length > 0,
                activities: data.activities.map(function(a, i) {
                    a.num = i + 1;
                    a.badgeclass = BADGES[a.status] || 'bg-secondary';
                    return a;
                })
            });
        });
        // The modal shows the title as HTML: escaped here.
        var title = request.then(function(data) {
            return escape(data.title);
        });
        return Modal.create({
            title: title,
            body: body,
            large: true,
            show: true,
            removeOnClose: true
        }).then(function(modal) {
            modal.getRoot().find('.modal-dialog').addClass('modal-xl');
            return modal;
        }).catch(Notification.exception);
    };

    var ids = function(tr) {
        var cell = tr && tr.querySelector(CELL);
        if (!cell) {
            return null;
        }
        return [parseInt(cell.dataset.userid, 10), parseInt(cell.dataset.courseid, 10)];
    };

    return {
        init: function() {
            var table = document.querySelector('.report-alucoursecompletion-table');
            if (!table) {
                return;
            }
            Str.get_string('clickrow', 'report_alucoursecompletion').then(function(label) {
                table.querySelectorAll(ROW).forEach(function(tr) {
                    tr.setAttribute('tabindex', '0');
                    tr.setAttribute('title', label);
                });
                return label;
            }).catch(Notification.exception);

            var handler = function(e) {
                var tr = e.target.closest(ROW);
                if (!tr || e.target.closest('a')) {
                    return;
                }
                if (e.type === 'keydown' && e.key !== 'Enter' && e.key !== ' ') {
                    return;
                }
                var id = ids(tr);
                if (!id) {
                    return;
                }
                e.preventDefault();
                openStudent(id[0], id[1]);
            };
            table.addEventListener('click', handler);
            table.addEventListener('keydown', handler);

            // Prefetch: mouse resting on a row (150 ms) or a row getting focus loads its details.
            var timer = null;
            var prefetch = function(e) {
                var id = ids(e.target.closest(ROW));
                clearTimeout(timer);
                if (!id) {
                    return;
                }
                timer = setTimeout(function() {
                    fetchStudent(id[0], id[1]).catch(function() {
                        return null;
                    });
                }, e.type === 'focusin' ? 0 : 150);
            };
            table.addEventListener('mouseover', prefetch);
            table.addEventListener('focusin', prefetch);
            table.addEventListener('mouseleave', function() {
                clearTimeout(timer);
            });
        }
    };
});
